package cn.iocoder.yudao.module.zsjos.controller.admin.gift;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.zsjos.controller.admin.gift.vo.*; import cn.iocoder.yudao.module.zsjos.service.gift.*; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; import static cn.iocoder.yudao.framework.common.pojo.CommonResult.success;
@Tag(name="管理后台-礼品配置") @RestController @RequestMapping("/zsjos/gift-config") public class GiftConfigController { @Resource GiftConfigService s; @PreAuthorize("hasAuthority('zsjos:gift-config:create')") @PostMapping("/create") public CommonResult<Long> create(@Valid @RequestBody GiftConfigSaveReqVO r){return success(s.create(r));} @PreAuthorize("hasAuthority('zsjos:gift-config:update')") @PutMapping("/update") public CommonResult<Boolean> update(@Valid @RequestBody GiftConfigSaveReqVO r){s.update(r);return success(true);} @PreAuthorize("hasAuthority('zsjos:gift-config:delete')") @DeleteMapping("/delete") public CommonResult<Boolean> delete(@RequestParam Long id){s.delete(id);return success(true);} @PreAuthorize("hasAuthority('zsjos:gift-config:query')") @GetMapping("/list") public CommonResult<List<?>> list(@RequestParam(required=false) Integer status){return success(s.list(status));} }
